def compute(vars):
    revenue_2019 = vars["v1"]
    revenue_2018 = vars["v2"]
    threshold = 25000000

    year = 2019 if revenue_2019 < threshold else 2018 if revenue_2018 < threshold else None

    return {
        "value": year,
        "trace": {
            "revenue_2019": revenue_2019,
            "revenue_2018": revenue_2018,
            "threshold": threshold,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
